screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#duplicate-tbody");
  const comparisonPanel = container.querySelector("#comparison-panel");
  const comparisonEmpty = container.querySelector("#comparison-empty");
  const comparisonContent = container.querySelector("#comparison-content");
  const comparisonTitle = container.querySelector("#comparison-title");
  const primaryDetails = container.querySelector("#primary-order-details");
  const secondaryDetails = container.querySelector("#secondary-order-details");
  const diffItems = container.querySelector("#diff-items");
  const matchingReason = container.querySelector("#matching-reason");

  let allDuplicates = [];
  let selectedPair = null;

  // 1. 重複受注一覧を再描画
  function renderDuplicateList(rows) {
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.マッチング信頼度 >= 90 ? '確実' : r.マッチング信頼度 >= 70 ? '高' : r.マッチング信頼度 >= 50 ? '中' : '低';
      const scoreColor = r.マッチング信頼度 >= 90 ? 'rgba(76,175,80,0.3)' : r.マッチング信頼度 >= 70 ? 'rgba(255,193,7,0.3)' : 'rgba(244,67,54,0.3)';
      const statusBadge = {
        '未確認': 'rgba(158,158,158,0.3)',
        '確認済み': 'rgba(33,150,243,0.3)',
        '統合済み': 'rgba(76,175,80,0.3)',
        '誤検出': 'rgba(244,67,54,0.3)'
      }[r.検出ステータス] || 'rgba(158,158,158,0.3)';

      return `
        <tr data-id="${r.重複受注検出結果ID}" class="duplicate-row" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.15s;">
          <td style="padding: 8px 10px; border-right: 1px solid rgba(255,255,255,0.08); color: var(--text);">${r.主受注ID?.substring(0, 8) || '-'}</td>
          <td style="padding: 8px 10px; border-right: 1px solid rgba(255,255,255,0.08); color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${r.顧客名 || '-'}</td>
          <td style="padding: 8px 10px; border-right: 1px solid rgba(255,255,255,0.08); text-align: center;">
            <span style="background: ${scoreColor}; padding: 3px 6px; border-radius: 2px; font-size: 11px; color: var(--text); font-weight: 600;">${r.マッチング信頼度}%</span>
          </td>
          <td style="padding: 8px 10px; text-align: center;">
            <span style="background: ${statusBadge}; padding: 3px 6px; border-radius: 2px; font-size: 11px; color: var(--text);">${r.検出ステータス}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    container.querySelectorAll(".duplicate-row").forEach(row => {
      row.addEventListener("click", () => selectPair(row.dataset.id));
    });
  }

  // 2. ペア選択時の比較表示
  function selectPair(pairId) {
    const pair = allDuplicates.find(d => d.重複受注検出結果ID === pairId);
    if (!pair) return;

    selectedPair = pair;
    comparisonEmpty.style.display = "none";
    comparisonContent.style.display = "block";
    comparisonTitle.textContent = `${pair.主受注ID?.substring(0, 8)} ↔ ${pair.副受注ID?.substring(0, 8)}`;

    // 主受注詳細
    primaryDetails.innerHTML = `
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">受注ID</td><td style="padding: 4px 6px; color: var(--text); font-weight: 600;">${pair.主受注ID?.substring(0, 12)}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">顧客名</td><td style="padding: 4px 6px; color: var(--text);">${pair.顧客名 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">受注日時</td><td style="padding: 4px 6px; color: var(--text);">${pair.受注日時 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">チャネル</td><td style="padding: 4px 6px; color: var(--text);">${pair.チャネル名 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">金額</td><td style="padding: 4px 6px; color: var(--text); font-weight: 600;">¥${(pair.金額 || 0).toLocaleString()}</td></tr>
    `;

    // 副受注詳細（サンプル）
    secondaryDetails.innerHTML = `
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">受注ID</td><td style="padding: 4px 6px; color: var(--text);">${pair.副受注ID?.substring(0, 12)}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">顧客名</td><td style="padding: 4px 6px; color: var(--text);">${pair.顧客名 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">受注日時</td><td style="padding: 4px 6px; color: var(--text);">${pair.受注日時 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">チャネル</td><td style="padding: 4px 6px; color: var(--text);">${pair.チャネル名 || '-'}</td></tr>
      <tr><td style="padding: 4px 6px; color: var(--text-muted); font-size: 11px;">金額</td><td style="padding: 4px 6px; color: var(--text); font-weight: 600;">¥${(pair.金額 || 0).toLocaleString()}</td></tr>
    `;

    // 差分表示
    diffItems.innerHTML = `
      <div style="background: rgba(255,100,100,0.15); padding: 6px 8px; border-radius: 2px; border-left: 3px solid rgba(255,100,100,0.5);">
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">金額相違</div>
        <div style="font-size: 12px; color: var(--text);">主: ¥${(pair.金額 || 0).toLocaleString()} / 副: ¥${((pair.金額 || 0) * 0.95).toLocaleString()}</div>
      </div>
    `;

    // マッチング理由
    matchingReason.innerHTML = `
      <div style="margin-bottom: 6px;"><strong>マッチング理由:</strong> ${pair.マッチング理由 || '顧客名・電話番号一致'}</div>
      <div style="margin-bottom: 6px;"><strong>信頼度:</strong> ${pair.マッチング信頼度}%</div>
      <div><strong>検出ルール:</strong> ${pair.検出ルールID || 'デフォルトルール'}</div>
    `;
  }

  // 3. 検索実行
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const keyword = container.querySelector("[data-testid='search-keyword']").value;
    const scoreFilter = container.querySelector("[data-testid='score-filter']").value;
    const channelFilter = container.querySelector("[data-testid='channel-filter']").value;
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;

    let filtered = allDuplicates;

    if (keyword) {
      filtered = filtered.filter(r => 
        (r.主受注ID || '').includes(keyword) || 
        (r.顧客名 || '').includes(keyword)
      );
    }

    if (scoreFilter) {
      const [min, max] = scoreFilter.split('-').map(Number);
      filtered = filtered.filter(r => r.マッチング信頼度 >= min && r.マッチング信頼度 <= max);
    }

    if (channelFilter) {
      filtered = filtered.filter(r => (r.チャネル名 || '').includes(channelFilter));
    }

    if (statusFilter) {
      filtered = filtered.filter(r => r.検出ステータス === statusFilter);
    }

    renderDuplicateList(filtered);
  });

  // 4. リセット
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='search-keyword']").value = "";
    container.querySelector("[data-testid='score-filter']").value = "";
    container.querySelector("[data-testid='channel-filter']").value = "";
    container.querySelector("[data-testid='status-filter']").value = "";
    renderDuplicateList(allDuplicates);
  });

  // 5. 重複確認ボタン
  container.querySelector("[data-testid='confirm-duplicate-button']").addEventListener("click", async () => {
    if (!selectedPair) return;
    const updated = await window.aivicApi.update(0, selectedPair.重複受注検出結果ID, { 検出ステータス: '確認済み' });
    if (updated) {
      alert("重複を確認しました");
      window.aivicApi.list(0).then(rows => {
        allDuplicates = rows;
        renderDuplicateList(rows);
      });
    }
  });

  // 6. 統合ボタン
  container.querySelector("[data-testid='merge-button']").addEventListener("click", async () => {
    if (!selectedPair) return;
    const updated = await window.aivicApi.update(0, selectedPair.重複受注検出結果ID, { 検出ステータス: '統合済み', 対応方針: '統合' });
    if (updated) {
      alert("受注を統合しました");
      window.aivicApi.list(0).then(rows => {
        allDuplicates = rows;
        renderDuplicateList(rows);
      });
    }
  });

  // 7. 誤検出ボタン
  container.querySelector("[data-testid='reject-button']").addEventListener("click", async () => {
    if (!selectedPair) return;
    const updated = await window.aivicApi.update(0, selectedPair.重複受注検出結果ID, { 検出ステータス: '誤検出' });
    if (updated) {
      alert("誤検出として記録しました");
      window.aivicApi.list(0).then(rows => {
        allDuplicates = rows;
        renderDuplicateList(rows);
      });
    }
  });

  // 8. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allDuplicates = rows || [];
    renderDuplicateList(allDuplicates);
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（入力漏れ検出結果テーブル）
  const TABLE_INDEX = 0;

  // 現在選択中の行データ
  let selectedRow = null;

  // 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#result-tbody");
    const count = container.querySelector("#result-count");
    count.textContent = rows.length;

    tbody.innerHTML = rows.map(r => {
      const priorityLabel = {
        '1': '最高', '2': '高', '3': '中', '4': '低', '5': '最低'
      }[String(r.優先度レベル || r.priority_level || '3')] || '中';

      const statusColor = {
        '未対応': 'rgba(255,106,0,0.2)',
        '対応中': 'rgba(255,215,0,0.2)',
        '完了': 'rgba(100,200,100,0.2)',
        '除外': 'rgba(128,128,128,0.2)'
      }[r.検出ステータス || r.detection_status || '未対応'] || 'rgba(128,128,128,0.2)';

      const statusTextColor = {
        '未対応': '#ff6a00',
        '対応中': '#ffd700',
        '完了': '#64c864',
        '除外': '#808080'
      }[r.検出ステータス || r.detection_status || '未対応'] || '#808080';

      return `
        <tr data-id="${r.入力漏れ検出結果ID || r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.受注ID || r.order_id || '—'}</td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.漏れ項目名 || r.missing_item_name || '—'}</td>
          <td style="padding: 8px 12px; text-align: center; border-right: 1px solid var(--border); color: var(--primary); font-weight: 600;">${priorityLabel}</td>
          <td style="padding: 8px 12px; text-align: center;">
            <span style="display: inline-block; padding: 3px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: ${statusColor}; color: ${statusTextColor};">
              ${r.検出ステータス || r.detection_status || '未対応'}
            </span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.addEventListener("click", () => {
        tbody.querySelectorAll("tr").forEach(t => t.style.background = "");
        tr.style.background = "rgba(255,106,0,0.1)";

        const rowId = tr.dataset.id;
        selectedRow = rows.find(r => (r.入力漏れ検出結果ID || r.id) === rowId);
        updateDetailPanel(selectedRow);
      });
    });
  }

  // 詳細パネル更新
  function updateDetailPanel(row) {
    if (!row) {
      container.querySelector("#detail-order-id").textContent = "—";
      container.querySelector("#detail-item-name").textContent = "—";
      container.querySelector("#detail-detected-at").textContent = "—";
      container.querySelector("#detail-confidence-score").textContent = "0%";
      container.querySelector("#detail-confidence-bar").style.width = "0%";
      container.querySelector("#detail-priority").textContent = "—";
      container.querySelector("#detail-importance").textContent = "—";
      container.querySelector("#detail-ocr-suggestion").textContent = "—";
      return;
    }

    const confidence = Math.min(100, Math.max(0, parseInt(row.信頼度スコア || row.confidence_score || 0)));
    const priorityLabel = {
      '1': '最高', '2': '高', '3': '中', '4': '低', '5': '最低'
    }[String(row.優先度レベル || row.priority_level || '3')] || '中';

    const importanceLabel = {
      '高': '高', '中': '中', '低': '低', '致命的': '致命的'
    }[row.重要度 || row.importance || '中'] || '中';

    container.querySelector("#detail-order-id").textContent = row.受注ID || row.order_id || "—";
    container.querySelector("#detail-item-name").textContent = row.漏れ項目名 || row.missing_item_name || "—";
    container.querySelector("#detail-detected-at").textContent = row.検出日時 || row.detected_at || "—";
    container.querySelector("#detail-confidence-score").textContent = confidence + "%";
    container.querySelector("#detail-confidence-bar").style.width = confidence + "%";
    container.querySelector("#detail-priority").textContent = priorityLabel;
    container.querySelector("#detail-importance").textContent = importanceLabel;
    container.querySelector("#detail-ocr-suggestion").textContent = row.AI_OCR提案値 || row.ocr_suggestion || "提案なし";

    // フォーム初期化
    container.querySelector("#input-correction-value").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#input-correction-note").value = "";
  }

  // 初期データ描画
  renderRows(tables[TABLE_INDEX]?.records || []);

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const itemName = container.querySelector("#filter-item-name").value.toLowerCase();
    const priority = container.querySelector("#filter-priority").value;
    const status = container.querySelector("#filter-status").value;

    const rows = await window.aivicApi.list(TABLE_INDEX) || tables[TABLE_INDEX]?.records || [];

    const filtered = rows.filter(r => {
      if (orderId && !(r.受注ID || r.order_id || "").toLowerCase().includes(orderId)) return false;
      if (itemName && !(r.漏れ項目名 || r.missing_item_name || "").toLowerCase().includes(itemName)) return false;
      if (priority && String(r.優先度レベル || r.priority_level || "3") !== priority) return false;
      if (status && (r.検出ステータス || r.detection_status || "未対応") !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(TABLE_INDEX) || tables[TABLE_INDEX]?.records || [];
    const headers = ["受注ID", "欠落項目", "優先度", "ステータス", "検出日時", "信頼度スコア"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注ID || r.order_id || "",
        r.漏れ項目名 || r.missing_item_name || "",
        {1:'最高',2:'高',3:'中',4:'低',5:'最低'}[String(r.優先度レベル || r.priority_level || '3')] || "中",
        r.検出ステータス || r.detection_status || "未対応",
        r.検出日時 || r.detected_at || "",
        r.信頼度スコア || r.confidence_score || "0"
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "missing_items_" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
  });

  // 修正保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!selectedRow) {
      alert("修正対象を選択してください");
      return;
    }

    const correctionValue = container.querySelector("#input-correction-value").value.trim();
    const correctionReason = container.querySelector("#input-correction-reason").value;
    const correctionNote = container.querySelector("#input-correction-note").value.trim();

    if (!correctionValue || !correctionReason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    // 修正履歴を保存（テーブルインデックス 1 と仮定）
    const correctionRecord = {
      受注データID: selectedRow.受注ID || selectedRow.order_id,
      修正項目名: selectedRow.漏れ項目名 || selectedRow.missing_item_name,
      修正前値: "",
      修正後値: correctionValue,
      修正理由: correctionReason,
      修正備考: correctionNote,
      修正ユーザーID: "current-user",
      修正日時: new Date().toISOString(),
      検証結果ID: selectedRow.入力漏れ検出結果ID || selectedRow.id
    };

    const saved = await window.aivicApi.save(1, correctionRecord);
    if (saved) {
      alert("修正を保存しました");
      // 入力漏れ検出結果のステータスを「完了」に更新
      await window.aivicApi.update(TABLE_INDEX, selectedRow.入力漏れ検出結果ID || selectedRow.id, {
        検出ステータス: "完了",
        修正済みフラグ: true,
        修正日時: new Date().toISOString()
      });

      // 再描画
      const rows = await window.aivicApi.list(TABLE_INDEX) || tables[TABLE_INDEX]?.records || [];
      renderRows(rows);
      updateDetailPanel(null);
    }
  });

  // キャンセル
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#input-correction-value").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#input-correction-note").value = "";
  });

  // 修正対象優先度リスト参照
  container.querySelector("#btn-view-priority-list").addEventListener("click", () => {
    window.showScreen("scr-1781413354977");
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const userInfo = container.querySelector("#user-info");
  const totalCount = container.querySelector("#total-count");
  const displayCount = container.querySelector("#display-count");

  const errorTypeFilter = container.querySelector("[data-testid='error-type-filter']");
  const priorityFilter = container.querySelector("[data-testid='priority-filter']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const confidenceMin = container.querySelector("[data-testid='confidence-min']");
  const confidenceMax = container.querySelector("[data-testid='confidence-max']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const resetBtn = container.querySelector("[data-testid='reset-button']");
  const exportBtn = container.querySelector("[data-testid='export-button']");

  let allRows = [];

  // ユーザー情報を表示（ダミー）
  userInfo.textContent = "ユーザー: admin@example.com";

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="height: 40px;"><td colspan="8" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">該当するデータがありません</td></tr>';
      displayCount.textContent = "0";
      return;
    }

    // 優先度でソート（昇順 = 1が最初）
    const sorted = [...rows].sort((a, b) => {
      const aPri = parseInt(a.優先度レベル || 5);
      const bPri = parseInt(b.優先度レベル || 5);
      return aPri - bPri;
    });

    tbody.innerHTML = sorted.map(r => {
      const priority = parseInt(r.優先度レベル || 5);
      const priorityLabel = ["最高", "高", "中", "低", "最低"][priority - 1] || "不明";
      const priorityColor = priority === 1 ? "#ff6a00" : priority === 2 ? "#ff9500" : priority === 3 ? "#ffc107" : "#9fb0d1";

      const confidence = parseInt(r.信頼度スコア || 0);
      const confidenceColor = confidence >= 80 ? "#4caf50" : confidence >= 60 ? "#ffc107" : "#ff6a00";

      const statusLabel = r.修正ステータス || "未対応";
      const statusBg = statusLabel === "完了" ? "rgba(76,175,80,0.15)" : statusLabel === "対応中" ? "rgba(255,193,7,0.15)" : statusLabel === "保留" ? "rgba(158,176,209,0.15)" : "rgba(255,106,0,0.15)";
      const statusColor = statusLabel === "完了" ? "#4caf50" : statusLabel === "対応中" ? "#ffc107" : statusLabel === "保留" ? "#9fb0d1" : "#ff6a00";

      const detectionDate = r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString("ja-JP", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—";

      return `<tr data-id="${r.優先度リストID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.06); hover: background: rgba(255,255,255,0.02);">
        <td style="padding: 10px 12px; text-align: center;">
          <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: rgba(255,106,0,0.15); color: ${priorityColor}; font-weight: 600; font-size: 11px;">${priorityLabel}</span>
        </td>
        <td style="padding: 10px 12px; color: var(--text); font-family: monospace; font-size: 11px;">${(r.受注データID || "—").substring(0, 8)}</td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 11px;">${r.チャネル || "—"}</td>
        <td style="padding: 10px 12px; color: var(--text); font-size: 11px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラー内容 || ""}">
          <strong>${r.エラー分類 || "—"}</strong><br/><span style="color: var(--text-muted); font-size: 10px;">${r.エラー内容 || "—"}</span>
        </td>
        <td style="padding: 10px 12px; text-align: center;">
          <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: rgba(${confidence >= 80 ? "76,175,80" : confidence >= 60 ? "255,193,7" : "255,106,0"},0.15); color: ${confidenceColor}; font-weight: 600; font-size: 11px;">${confidence}%</span>
        </td>
        <td style="padding: 10px 12px; color: var(--text-muted); font-size: 11px;">${detectionDate}</td>
        <td style="padding: 10px 12px;">
          <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${statusBg}; color: ${statusColor}; font-weight: 500; font-size: 11px;">${statusLabel}</span>
        </td>
        <td style="padding: 10px 12px; text-align: center; display: flex; gap: 4px; justify-content: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.優先度リストID || r.id}" style="padding: 4px 8px; font-size: 10px;">詳細</button>
          <button class="action-btn secondary edit-btn" data-id="${r.優先度リストID || r.id}" style="padding: 4px 8px; font-size: 10px;">修正</button>
        </td>
      </tr>`;
    }).join("");

    displayCount.textContent = sorted.length.toString();
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      allRows = rows;
      totalCount.textContent = rows.length.toString();
      renderRows(rows);
    }
  });

  // 検索ボタン
  searchBtn.addEventListener("click", () => {
    const errorType = errorTypeFilter.value;
    const priority = priorityFilter.value;
    const status = statusFilter.value;
    const minConf = parseInt(confidenceMin.value) || 0;
    const maxConf = parseInt(confidenceMax.value) || 100;

    const filtered = allRows.filter(r => {
      if (errorType && r.エラー分類 !== errorType) return false;
      if (priority && parseInt(r.優先度レベル || 5) !== parseInt(priority)) return false;
      if (status && r.修正ステータス !== status) return false;
      const conf = parseInt(r.信頼度スコア || 0);
      if (conf < minConf || conf > maxConf) return false;
      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  resetBtn.addEventListener("click", () => {
    errorTypeFilter.value = "";
    priorityFilter.value = "";
    statusFilter.value = "";
    confidenceMin.value = "";
    confidenceMax.value = "";
    renderRows(allRows);
  });

  // CSVエクスポート
  exportBtn.addEventListener("click", () => {
    if (!allRows || allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["優先度レベル", "受注データID", "チャネル", "エラー分類", "エラー内容", "信頼度スコア", "検証実行日時", "修正ステータス"];
    const rows = allRows.map(r => [
      r.優先度レベル || "",
      r.受注データID || "",
      r.チャネル || "",
      r.エラー分類 || "",
      r.エラー内容 || "",
      r.信頼度スコア || "",
      r.検証実行日時 || "",
      r.修正ステータス || ""
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell || "");
        return str.includes(",") || str.includes('"') || str.includes("\n") 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `修正対象優先度リスト_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 行レベルイベント（詳細・修正）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === id || r.id === id);
      if (row) {
        // 詳細画面へ遷移（受注データ詳細確認・修正画面）
        window.showScreen("scr-1781413282852");
      }
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === id || r.id === id);
      if (row) {
        // 修正画面へ遷移（受注データ修正画面）
        window.showScreen("scr-1781413732217");
      }
      return;
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0 = 受注データ検証結果
  const tableIndex = 0;
  const pageSize = 20;
  let currentPage = 1;
  let allRows = [];
  let filteredRows = [];

  // 1. 信頼度スコア分布グラフを描画
  function renderScoreDistributionChart() {
    const canvas = container.querySelector("#score-distribution-chart");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    // 背景クリア
    ctx.fillStyle = "rgba(0,0,0,0)";
    ctx.fillRect(0, 0, width, height);

    // スコア分布データ（サンプル）
    const ranges = [
      { label: "0-20", count: 5, color: "#ef4444" },
      { label: "21-40", count: 12, color: "#f59e0b" },
      { label: "41-60", count: 28, color: "#3b82f6" },
      { label: "61-80", count: 95, color: "#10b981" },
      { label: "81-100", count: 1107, color: "#4ade80" }
    ];

    const maxCount = Math.max(...ranges.map(r => r.count));
    const barWidth = width / ranges.length;
    const padding = 10;

    ranges.forEach((range, i) => {
      const barHeight = (range.count / maxCount) * (height - padding * 2);
      const x = i * barWidth + barWidth * 0.1;
      const y = height - barHeight - padding;

      ctx.fillStyle = range.color;
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);

      // ラベル
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(range.label, x + barWidth * 0.4, height - 2);
    });
  }

  // 2. 検証結果テーブルを再描画
  function renderValidationResults(rows) {
    const tbody = container.querySelector("#validation-results-tbody");
    if (!tbody) return;

    const start = (currentPage - 1) * pageSize;
    const end = start + pageSize;
    const pageRows = rows.slice(start, end);

    tbody.innerHTML = pageRows.map(row => {
      const statusColor = {
        "合格": "#4ade80",
        "不合格": "#ef4444",
        "警告": "#f59e0b",
        "保留": "#8b5cf6"
      }[row.検証ステータス] || "#9fb0d1";

      const priorityLabel = {
        1: "最高",
        2: "高",
        3: "中",
        4: "低",
        5: "最低"
      }[row.修正優先度] || "—";

      const priorityColor = {
        1: "#ef4444",
        2: "#f59e0b",
        3: "#3b82f6",
        4: "#10b981",
        5: "#9fb0d1"
      }[row.修正優先度] || "#9fb0d1";

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;" data-id="${row.検証結果ID}" class="result-row">
          <td style="padding: 0.75rem; color: var(--text);">${row.受注データID?.substring(0, 8) || "—"}</td>
          <td style="padding: 0.75rem; color: var(--text);">${row.チャネル名 || "—"}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.75rem; background: ${statusColor}20; color: ${statusColor}; border-radius: 0.25rem; font-size: 0.8rem; font-weight: 600;">
              ${row.検証ステータス || "—"}
            </span>
          </td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); font-weight: 600;">${row.総合スコア || "—"}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.8rem;">${row.エラーメッセージ?.substring(0, 40) || "—"}${row.エラーメッセージ?.length > 40 ? "..." : ""}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.75rem; background: ${priorityColor}20; color: ${priorityColor}; border-radius: 0.25rem; font-size: 0.8rem; font-weight: 600;">
              ${priorityLabel}
            </span>
          </td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text-muted);">${row.対応状況 || "未対応"}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.検証結果ID}" style="padding: 0.4rem 0.75rem; font-size: 0.8rem;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    // ページネーション更新
    const totalPages = Math.ceil(rows.length / pageSize);
    container.querySelector("#current-page").textContent = currentPage;
    container.querySelector("#total-pages").textContent = totalPages;
  }

  // 3. 初期データ読み込みと描画
  async function initializeData() {
    const rows = tables[0]?.records || [];
    allRows = rows;
    filteredRows = rows;
    renderValidationResults(filteredRows);
    renderScoreDistributionChart();
  }

  // 4. 検索ボタンのイベントリスナー
  container.querySelector("#search-button")?.addEventListener("click", () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    filteredRows = allRows.filter(row => {
      const rowDate = new Date(row.検証実行日時);
      const fromDate = dateFrom ? new Date(dateFrom) : new Date("1900-01-01");
      const toDate = dateTo ? new Date(dateTo) : new Date("2099-12-31");

      const dateMatch = rowDate >= fromDate && rowDate <= toDate;
      const channelMatch = !channel || row.チャネル名 === channel;
      const statusMatch = !status || row.検証ステータス === status;

      return dateMatch && channelMatch && statusMatch;
    });

    currentPage = 1;
    renderValidationResults(filteredRows);
  });

  // 5. リセットボタンのイベントリスナー
  container.querySelector("#reset-button")?.addEventListener("click", () => {
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-status").value = "";
    filteredRows = allRows;
    currentPage = 1;
    renderValidationResults(filteredRows);
  });

  // 6. CSVエクスポートボタン
  container.querySelector("#export-csv-button")?.addEventListener("click", () => {
    const headers = ["受注ID", "チャネル", "検証ステータス", "信頼度スコア", "エラー内容", "修正優先度", "対応状況"];
    const rows = filteredRows.map(row => [
      row.受注データID?.substring(0, 8) || "",
      row.チャネル名 || "",
      row.検証ステータス || "",
      row.総合スコア || "",
      row.エラーメッセージ || "",
      row.修正優先度 || "",
      row.対応状況 || ""
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "validation_results.csv";
    link.click();
  });

  // 7. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852");
    }
  });

  // 8. 初期化実行
  initializeData();
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 状態管理
  // ============================================
  let currentStep = 1;
  let totalSteps = 5;
  let guidanceTime = 0;
  let guidanceDuration = 150; // 2:30
  let isGuidancePlaying = false;
  let ocrInProgress = false;
  let extractedData = [];
  let currentImageData = null;

  // ============================================
  // 2. UI更新関数
  // ============================================
  function updateGuidanceDisplay() {
    const steps = [
      "ステップ 1/5: 受注者名を確認してください",
      "ステップ 2/5: 受注金額を確認してください",
      "ステップ 3/5: 配送先住所を確認してください",
      "ステップ 4/5: 商品名と数量を確認してください",
      "ステップ 5/5: 受注日と配送日を確認してください"
    ];
    container.querySelector("#current-step").textContent = steps[currentStep - 1] || steps[0];
  }

  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${String(secs).padStart(2, '0')}`;
  }

  function updateGuidanceTime() {
    container.querySelector("#guidance-time").textContent = formatTime(guidanceTime);
  }

  function renderExtractedData() {
    const tbody = container.querySelector("#extracted-tbody");
    if (!extractedData || extractedData.length === 0) {
      tbody.innerHTML = `<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">
        データがまだ抽出されていません
      </td></tr>`;
      return;
    }

    const lowConfidenceItems = extractedData.filter(d => d.confidence < 70);

    tbody.innerHTML = extractedData.map(d => {
      const isLowConfidence = d.confidence < 70;
      const bgColor = isLowConfidence ? 'rgba(255,107,0,0.08)' : 'transparent';
      return `<tr style="border-bottom: 1px solid var(--border); background: ${bgColor};">
        <td style="padding: 6px 4px; color: var(--text);">${d.field}</td>
        <td style="padding: 6px 4px; color: var(--text);">${d.value}</td>
        <td style="padding: 6px 4px; text-align: center; color: ${isLowConfidence ? '#ff6b00' : 'var(--text)'}; font-weight: ${isLowConfidence ? '600' : '400'};">
          ${d.confidence}%
        </td>
      </tr>`;
    }).join("");

    // 低信頼度アラート表示
    const alertEl = container.querySelector("#low-confidence-alert");
    if (lowConfidenceItems.length > 0) {
      alertEl.style.display = "block";
      const listHtml = lowConfidenceItems.map(d => `<div>• ${d.field}: ${d.confidence}%</div>`).join("");
      container.querySelector("#low-confidence-list").innerHTML = listHtml;
    } else {
      alertEl.style.display = "none";
    }

    // 総合信頼度スコア
    const avgConfidence = Math.round(extractedData.reduce((sum, d) => sum + d.confidence, 0) / extractedData.length);
    container.querySelector("#overall-confidence").textContent = `信頼度: ${avgConfidence}%`;
  }

  // ============================================
  // 3. イベントリスナー登録
  // ============================================

  // 音声ガイダンス再生
  container.querySelector("#btn-play-guidance").addEventListener("click", () => {
    isGuidancePlaying = true;
    const interval = setInterval(() => {
      guidanceTime++;
      updateGuidanceTime();
      if (guidanceTime >= guidanceDuration) {
        clearInterval(interval);
        isGuidancePlaying = false;
        guidanceTime = 0;
        updateGuidanceTime();
      }
    }, 1000);
  });

  // 音声ガイダンス一時停止
  container.querySelector("#btn-pause-guidance").addEventListener("click", () => {
    isGuidancePlaying = false;
  });

  // 音量調整
  container.querySelector("#guidance-volume").addEventListener("input", (e) => {
    container.querySelector("#volume-display").textContent = e.target.value;
  });

  // カメラ起動
  container.querySelector("#btn-camera").addEventListener("click", () => {
    alert("カメラを起動しました（デモ）");
    // 実装: navigator.mediaDevices.getUserMedia() で実際のカメラアクセス
  });

  // スキャナ起動
  container.querySelector("#btn-scanner").addEventListener("click", () => {
    alert("スキャナを起動しました（デモ）");
  });

  // 撮影ボタン
  container.querySelector("#btn-capture").addEventListener("click", () => {
    currentImageData = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";
    container.querySelector("#image-preview").innerHTML = `<img src="${currentImageData}" style="width: 100%; height: 100%; object-fit: contain;">`;
    alert("撮影しました（デモ画像）");
  });

  // OCR読み込み開始
  container.querySelector("#btn-start-ocr").addEventListener("click", async () => {
    if (!currentImageData) {
      alert("先に撮影してください");
      return;
    }

    ocrInProgress = true;
    container.querySelector("#ocr-status").textContent = "処理中...";
    container.querySelector("#btn-start-ocr").disabled = true;

    // 進捗シミュレーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      container.querySelector("#ocr-progress").style.width = progress + "%";
      container.querySelector("#ocr-progress-text").textContent = Math.round(progress);
    }, 300);

    // デモ用の抽出データ
    setTimeout(() => {
      clearInterval(progressInterval);
      container.querySelector("#ocr-progress").style.width = "100%";
      container.querySelector("#ocr-progress-text").textContent = "100";
      container.querySelector("#ocr-status").textContent = "完了";

      extractedData = [
        { field: "顧客名", value: "山田太郎", confidence: 95 },
        { field: "受注金額", value: "¥150,000", confidence: 88 },
        { field: "受注日", value: "2025-01-15", confidence: 92 },
        { field: "配送日", value: "2025-01-20", confidence: 65 },
        { field: "商品名", value: "プロダクトA", confidence: 78 },
        { field: "数量", value: "5", confidence: 91 }
      ];

      renderExtractedData();
      ocrInProgress = false;
      container.querySelector("#btn-start-ocr").disabled = false;

      // 3秒後にリセット
      setTimeout(() => {
        container.querySelector("#ocr-progress").style.width = "0%";
        container.querySelector("#ocr-progress-text").textContent = "0";
        container.querySelector("#ocr-status").textContent = "待機中";
      }, 3000);
    }, 2000);
  });

  // 修正を適用
  container.querySelector("#btn-apply-correction").addEventListener("click", async () => {
    const field = container.querySelector("#correction-field").value;
    const value = container.querySelector("#correction-value").value;
    const reason = container.querySelector("#correction-reason").value;

    if (!field || !value || !reason) {
      alert("すべての項目を入力してください");
      return;
    }

    // 抽出データ内の該当項目を更新
    const idx = extractedData.findIndex(d => d.field === field);
    if (idx >= 0) {
      extractedData[idx].value = value;
      extractedData[idx].confidence = 100; // 手動修正は信頼度100%
    }

    renderExtractedData();

    // 修正履歴を保存（デモ）
    const correctionRecord = {
      field,
      original_value: extractedData[idx]?.value || "",
      corrected_value: value,
      reason,
      timestamp: new Date().toISOString()
    };
    console.log("修正記録:", correctionRecord);

    alert("修正を適用しました");
    container.querySelector("#correction-field").value = "";
    container.querySelector("#correction-value").value = "";
    container.querySelector("#correction-reason").value = "";
  });

  // クリアボタン
  container.querySelector("#btn-clear-correction").addEventListener("click", () => {
    container.querySelector("#correction-field").value = "";
    container.querySelector("#correction-value").value = "";
    container.querySelector("#correction-reason").value = "";
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    if (currentStep > 1) {
      currentStep--;
      updateGuidanceDisplay();
    } else {
      window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボード
    }
  });

  // 次へボタン
  container.querySelector("#btn-next").addEventListener("click", () => {
    if (currentStep < totalSteps) {
      currentStep++;
      updateGuidanceDisplay();
    } else {
      // 最終ステップから次へ → 詳細確認・修正画面へ
      window.showScreen("scr-1781413282852");
    }
  });

  // ============================================
  // 4. 初期化
  // ============================================
  updateGuidanceDisplay();
  updateGuidanceTime();
  renderExtractedData();
}

