          <td style="padding: 8px 10px; text-align: center; color: var(--text);">${r.一貫性スコア || 0}</td>
          <td style="padding: 8px 10px; color: var(--text);">${r.検証ステータス || '-'}</td>
          <td style="padding: 8px 10px; color: var(--text);">${r.チャネル || '-'}</td>
          <td style="padding: 8px 10px; text-align: center;">${warningBadge}</td>
          <td style="padding: 8px 10px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    resultCount.textContent = `結果: ${rows.length}件`;
    drawHistogram(rows);
  }

  // 2. スコア分布ヒストグラム描画
  function drawHistogram(rows) {
    if (!ctx) return;
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // スコア範囲を10段階に分割
    const bins = Array(10).fill(0);
    rows.forEach(r => {
      const score = r.総合スコア || 0;
      const bin = Math.min(Math.floor(score / 10), 9);
      bins[bin]++;
    });

    const maxBin = Math.max(...bins, 1);
    const barWidth = w / 10;
    const padding = 4;

    bins.forEach((count, i) => {
      const barHeight = (count / maxBin) * (h - 20);
      const x = i * barWidth + padding;
      const y = h - barHeight - 10;

      // グラデーション背景（金→赤）
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, '#fbbf24');
      gradient.addColorStop(1, '#ef4444');

      ctx.fillStyle = gradient;
      ctx.fillRect(x, y, barWidth - padding * 2, barHeight);

      // ラベル
      ctx.fillStyle = '#d0e4ff';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${i * 10}-${(i + 1) * 10}`, x + (barWidth - padding * 2) / 2, h - 2);
    });
  }

  // 3. フィルタ関数
  function applyFilters() {
    const scoreMin = parseInt(container.querySelector("#score-min").value) || 0;
    const scoreMax = parseInt(container.querySelector("#score-max").value) || 100;
    const status = container.querySelector("#status-filter").value;
    const channel = container.querySelector("#channel-filter").value;
    const validationResult = container.querySelector("#validation-result-filter").value;
    const warningLevel = container.querySelector("#warning-level-filter").value;
    const ocrConfidence = container.querySelector("#ocr-confidence-filter").value;
    const dateFrom = container.querySelector("#date-from").value;
    const flagDuplicate = container.querySelector("#flag-duplicate").checked;
    const flagChannelConflict = container.querySelector("#flag-channel-conflict").checked;
    const flagMissingInput = container.querySelector("#flag-missing-input").checked;
    const flagHasHistory = container.querySelector("#flag-has-history").checked;

    let filtered = allRows.filter(r => {
      const score = r.総合スコア || 0;
      if (score < scoreMin || score > scoreMax) return false;
      if (status && r.検証ステータス !== status) return false;
      if (channel && r.チャネル !== channel) return false;
      if (validationResult && r.検証結果 !== validationResult) return false;
      if (warningLevel && r.警告レベル !== warningLevel) return false;
      if (flagDuplicate && !r.重複フラグ) return false;
      if (flagChannelConflict && !r.チャネル矛盾フラグ) return false;
      if (flagMissingInput && !r.入力漏れフラグ) return false;
      if (flagHasHistory && !r.修正履歴有) return false;
      if (ocrConfidence) {
        const ocr = r.AI_OCR信頼度 || 0;
        if (ocrConfidence === "80-100" && ocr < 80) return false;
        if (ocrConfidence === "60-79" && (ocr < 60 || ocr >= 80)) return false;
        if (ocrConfidence === "0-59" && ocr >= 60) return false;
      }
      if (dateFrom) {
        const rowDate = r.検証実行日時 ? r.検証実行日時.split('T')[0] : '';
        if (rowDate < dateFrom) return false;
      }
      return true;
    });

    // フィルタサマリー更新
    const conditions = [];
    if (scoreMin > 0 || scoreMax < 100) conditions.push(`スコア: ${scoreMin}-${scoreMax}`);
    if (status) conditions.push(`ステータス: ${status}`);
    if (channel) conditions.push(`チャネル: ${channel}`);
    if (warningLevel) conditions.push(`警告: ${warningLevel}`);
    if (flagDuplicate) conditions.push('重複検出');
    if (flagChannelConflict) conditions.push('チャネル矛盾');
    if (flagMissingInput) conditions.push('入力漏れ');
    if (flagHasHistory) conditions.push('修正履歴有');
    filterSummary.textContent = conditions.length > 0 ? `フィルタ条件: ${conditions.join(' / ')}` : 'フィルタ条件: なし';

    renderRows(filtered);
  }

  // 4. 初期データ描画
  renderRows(allRows);

  // 5. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    applyFilters();
  });

  // 6. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#score-min").value = "0";
    container.querySelector("#score-max").value = "100";
    container.querySelector("#status-filter").value = "";
    container.querySelector("#channel-filter").value = "";
    container.querySelector("#validation-result-filter").value = "";
    container.querySelector("#warning-level-filter").value = "";
    container.querySelector("#ocr-confidence-filter").value = "";
    container.querySelector("#date-from").value = "";
    container.querySelector("#flag-duplicate").checked = false;
    container.querySelector("#flag-channel-conflict").checked = false;
    container.querySelector("#flag-missing-input").checked = false;
    container.querySelector("#flag-has-history").checked = false;
    renderRows(allRows);
    filterSummary.textContent = 'フィルタ条件: なし';
  });

  // 7. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = tbody.querySelectorAll("tr");
    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "総合スコア", "完全性", "正確性", "一貫性", "ステータス", "チャネル", "警告"];
    const csv = [headers.join(",")];

    const visibleRows = Array.from(tbody.querySelectorAll("tr")).filter(tr => tr.cells.length > 1);
    visibleRows.forEach(tr => {
      const cells = Array.from(tr.cells).slice(0, 8).map(td => {
        let text = td.textContent.trim();
        if (text.includes(",") || text.includes('"')) text = `"${text.replace(/"/g, '""')}"`;
        return text;
      });
      csv.push(cells.join(","));
    });

    const bom = "\uFEFF";
    const blob = new Blob([bom + csv.join("\n")], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `score-filter-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 8. 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.id === id);
      if (row) {
        // 詳細画面へ遷移
        window.showScreen("scr-1781413282852");
      }
    }
  });

  // 9. スライダー連動
  container.querySelector("#score-slider").addEventListener("input", e => {
    container.querySelector("#score-min").value = e.target.value;
  });

  // 10. Enter キーで検索
  container.addEventListener("keypress", e => {
    if (e.key === "Enter" && e.target.tagName === "INPUT") {
      applyFilters();
    }
  });
}

