  const diffPanel = container.querySelector("#diff-panel");
  const modifierPanel = container.querySelector("#modifier-panel");
  const scorePanel = container.querySelector("#score-panel");
  const rulesPanel = container.querySelector("#rules-panel");
  const errorsPanel = container.querySelector("#errors-panel");
  const duplicatesPanel = container.querySelector("#duplicates-panel");
  const contradictionsPanel = container.querySelector("#contradictions-panel");
  const detailModal = container.querySelector("#detail-modal");
  const modalTitle = container.querySelector("#modal-title");
  const modalContent = container.querySelector("#modal-content");

  let selectedOrderId = null;
  let allRecords = [];

  // 1. 再描画関数
  function renderRows(rows) {
    allRecords = rows;
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "color: #4ade80;" : 
                          r.検証ステータス === "不合格" ? "color: #ef4444;" :
                          r.検証ステータス === "警告" ? "color: #f59e0b;" : "color: var(--text-muted);";
      return `
        <tr data-id="${r.検証結果ID || ''}" style="border-bottom: 1px solid var(--border); hover: background: var(--bg-main);">
          <td style="padding: 8px 12px; color: var(--text);">${r.受注データID ? r.受注データID.substring(0, 8) : '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.検証項目 || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text);">${r.修正ユーザーID ? r.修正ユーザーID.substring(0, 8) : '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.修正日時 ? new Date(r.修正日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 8px 12px; text-align: center; ${statusColor}">${r.検証ステータス || '-'}</td>
          <td style="padding: 8px 12px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || ''}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  renderRows(tables[TABLE_VALIDATION_RESULTS]?.records || []);

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#search-order-id").value.trim();
    const status = container.querySelector("#filter-status").value;

    let filtered = allRecords;
    if (orderId) {
      filtered = filtered.filter(r => (r.受注データID || '').includes(orderId));
    }
    if (status) {
      filtered = filtered.filter(r => r.検証ステータス === status);
    }
    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-refresh").addEventListener("click", () => {
    container.querySelector("#search-order-id").value = "";
    container.querySelector("#filter-status").value = "";
    renderRows(allRecords);
  });

  // 4. 詳細表示（イベントデリゲーション）
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const validationId = detailBtn.dataset.id;
      selectedOrderId = validationId;

      // 検証結果を取得
      const validation = allRecords.find(r => r.検証結果ID === validationId);
      if (!validation) return;

      // 修正履歴を取得
      const correctionHistory = tables[TABLE_CORRECTION_HISTORY]?.records || [];
      const corrections = correctionHistory.filter(c => c.受注データID === validation.受注データID);

      // 信頼度スコアを取得
      const trustScores = tables[TABLE_TRUST_SCORE]?.records || [];
      const trustScore = trustScores.find(s => s.受注データID === validation.受注データID);

      // 重複検出結果を取得
      const duplicates = tables[TABLE_DUPLICATES]?.records || [];
      const dupResults = duplicates.filter(d => d.主受注ID === validation.受注データID || d.副受注ID === validation.受注データID);

      // チャネル間矛盾を取得
      const contradictions = tables[TABLE_CONTRADICTIONS]?.records || [];
      const contResults = contradictions.filter(c => c.受注ID_1 === validation.受注データID || c.受注ID_2 === validation.受注データID);

      // 差分表示
      if (corrections.length > 0) {
        const lastCorrection = corrections[corrections.length - 1];
        container.querySelector("#diff-before").textContent = `${lastCorrection.修正項目名}: ${lastCorrection.修正前値}`;
        container.querySelector("#diff-after").textContent = `${lastCorrection.修正項目名}: ${lastCorrection.修正後値}`;
        diffPanel.style.display = "block";
      }

      // 修正者情報
      if (corrections.length > 0) {
        const lastCorrection = corrections[corrections.length - 1];
        container.querySelector("#modifier-name").textContent = lastCorrection.修正ユーザーID || '-';
        container.querySelector("#modifier-date").textContent = lastCorrection.修正日時 ? new Date(lastCorrection.修正日時).toLocaleString('ja-JP') : '-';
        container.querySelector("#modifier-reason").textContent = lastCorrection.修正理由 || '-';
        container.querySelector("#modifier-notes").textContent = lastCorrection.修正備考 || '-';
        modifierPanel.style.display = "block";
      }

      // 信頼度スコア
      if (trustScore) {
        container.querySelector("#score-total").textContent = trustScore.総合スコア || '0';
        container.querySelector("#score-completeness").textContent = trustScore.完全性スコア || '0';
        container.querySelector("#score-accuracy").textContent = trustScore.正確性スコア || '0';
        container.querySelector("#score-consistency").textContent = trustScore.一貫性スコア || '0';
        scorePanel.style.display = "block";
      }

      // 検証ルール適用状況
      const rulesList = container.querySelector("#rules-list");
      rulesList.innerHTML = `
        <div style="padding: 8px; background: var(--bg-main); border-radius: 4px; border-left: 3px solid var(--primary);">
          <div style="font-weight: 500; color: var(--text);">ルールID: ${validation.検証ルールID || '-'}</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-top: 4px;">
            検証項目: ${validation.検証項目 || '-'} | 重要度: ${validation.重要度 || '-'}
          </div>
        </div>
      `;
      rulesPanel.style.display = "block";

      // エラー・警告
      if (validation.エラーコード || validation.エラーメッセージ) {
        const errorsList = container.querySelector("#errors-list");
        errorsList.innerHTML = `
          <div style="padding: 8px; background: rgba(239,68,68,0.1); border-radius: 4px; border-left: 3px solid #ef4444;">
            <div style="font-weight: 500; color: #ef4444;">エラーコード: ${validation.エラーコード || '-'}</div>
            <div style="font-size: 12px; color: var(--text); margin-top: 4px;">${validation.エラーメッセージ || '-'}</div>
          </div>
        `;
        errorsPanel.style.display = "block";
      }

      // 重複受注検出結果
      if (dupResults.length > 0) {
        const dupsList = container.querySelector("#duplicates-list");
        dupsList.innerHTML = dupResults.map(d => `
          <div style="padding: 8px; background: var(--bg-main); border-radius: 4px; margin-bottom: 8px; border-left: 3px solid #f59e0b;">
            <div style="font-weight: 500; color: var(--text);">マッチング信頼度: ${d.マッチング信頼度}%</div>
            <div style="font-size: 12px; color: var(--text-muted); margin-top: 4px;">${d.マッチング理由 || '-'}</div>
            <div style="font-size: 12px; color: var(--text-muted);">ステータス: ${d.検出ステータス || '-'}</div>
          </div>
        `).join("");
        duplicatesPanel.style.display = "block";
      }

      // チャネル間矛盾検出結果
      if (contResults.length > 0) {
        const contsList = container.querySelector("#contradictions-list");
        contsList.innerHTML = contResults.map(c => `
          <div style="padding: 8px; background: var(--bg-main); border-radius: 4px; margin-bottom: 8px; border-left: 3px solid #ef4444;">
            <div style="font-weight: 500; color: var(--text);">矛盾タイプ: ${c.矛盾タイプ || '-'}</div>
            <div style="font-size: 12px; color: var(--text-muted); margin-top: 4px;">${c.矛盾内容 || '-'}</div>
            <div style="font-size: 12px; color: var(--text-muted);">重要度: ${c.重要度 || '-'} | ステータス: ${c.ステータス || '-'}</div>
          </div>
        `).join("");
        contradictionsPanel.style.display = "block";
      }
    }
  });

  // 5. 再検証実行ボタン
  container.querySelector("#btn-revalidate").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("再検証対象を選択してください");
      return;
    }
    alert("再検証処理を実行します（実装予定）");
    // 実装: 選択された検証結果に対して再検証処理を実行
  });

  // 6. 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("承認対象を選択してください");
      return;
    }
    if (confirm("この修正データを承認しますか？")) {
      alert("承認処理を実行します（実装予定）");
      // 実装: 連携承認フロー更新
    }
  });

  // 7. キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボードへ
  });

  // 8. モーダル閉じる
  container.querySelector("#modal-close").addEventListener("click", () => {
    detailModal.style.display = "none";
  });

  detailModal.addEventListener("click", e => {
    if (e.target === detailModal) {
      detailModal.style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（連携承認フロー = 0, 受注データ検証結果 = 1, 入力漏れ検出結果 = 2, チャネル間矛盾検出結果 = 3, 受注データ修正履歴 = 4）
  const flowTableIndex = 0;
  const validationTableIndex = 1;
  const missingTableIndex = 2;
  const conflictTableIndex = 3;
  const correctionTableIndex = 4;

  let selectedOrderId = null;
  let currentFlowData = null;

  // 1. 受注一覧を再描画
  function renderOrderList(rows) {
    const tbody = container.querySelector("#order-tbody");
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.信頼度スコア >= 80 ? 'style="color: #4ade80;"' : r.信頼度スコア >= 60 ? 'style="color: #facc15;"' : 'style="color: #ff6b6b;"';
      return `
        <tr data-id="${r.受注データID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; color: var(--text);">${(r.受注ID || r.id || '').substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text);">${r.顧客名 || r.customer_name || '-'}</td>
          <td style="padding: 8px; text-align: center; ${scoreClass}">${r.信頼度スコア || r.confidence_score || 0}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${r.現在ステータス === '待機中' ? 'rgba(255,193,7,0.2)' : r.現在ステータス === '承認済' ? 'rgba(76,175,80,0.2)' : 'rgba(244,67,54,0.2)'}; color: ${r.現在ステータス === '待機中' ? '#facc15' : r.現在ステータス === '承認済' ? '#4ade80' : '#ff6b6b'};">${r.現在ステータス || r.status || '待機中'}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll("#order-tbody tr").forEach(tr => {
      tr.addEventListener("click", () => {
        selectedOrderId = tr.dataset.id;
        loadDetailPanel(selectedOrderId);
        container.querySelectorAll("#order-tbody tr").forEach(t => t.style.background = "");
        tr.style.background = "rgba(255,255,255,0.1)";
      });
    });
  }

  // 2. 詳細パネルをロード
  function loadDetailPanel(orderId) {
    const detailPanel = container.querySelector("#detail-panel");
    const noSelection = container.querySelector("#no-selection");

    // 検証結果を取得
    const validationResult = (tables[validationTableIndex]?.records || []).find(r => r.受注データID === orderId || r.order_id === orderId);
    const missingItems = (tables[missingTableIndex]?.records || []).filter(r => r.受注ID === orderId || r.order_id === orderId);
    const conflicts = (tables[conflictTableIndex]?.records || []).filter(r => r.受注ID_1 === orderId || r.order_id_1 === orderId);
    const corrections = (tables[correctionTableIndex]?.records || []).filter(r => r.受注データID === orderId || r.order_id === orderId);
    const flowData = (tables[flowTableIndex]?.records || []).find(r => r.受注データID === orderId || r.order_id === orderId);

    currentFlowData = flowData;

    // 詳細情報を埋める
    container.querySelector("#detail-order-id").textContent = (orderId || '').substring(0, 8);
    container.querySelector("#detail-customer").textContent = validationResult?.顧客名 || validationResult?.customer_name || '-';
    container.querySelector("#detail-amount").textContent = validationResult?.受注金額 ? `¥${parseInt(validationResult.受注金額).toLocaleString()}` : '-';
    container.querySelector("#detail-channel").textContent = validationResult?.チャネル || validationResult?.channel || '-';
    container.querySelector("#detail-date").textContent = validationResult?.受注日時 ? new Date(validationResult.受注日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#detail-score").textContent = `${validationResult?.信頼度スコア || 0}%`;

    // 検出問題
    const issuesList = container.querySelector("#issues-list");
    issuesList.innerHTML = validationResult ? `
      <div style="padding: 6px; background: rgba(255,107,107,0.1); border-left: 3px solid #ff6b6b; border-radius: 3px;">
        <div style="font-weight: 600; color: #ff6b6b; margin-bottom: 2px;">${validationResult.エラーコード || 'ERR-001'}</div>
        <div style="color: var(--text); font-size: 11px;">${validationResult.エラーメッセージ || validationResult.error_message || '検証エラーが検出されました'}</div>
        <div style="color: var(--text-muted); font-size: 10px; margin-top: 4px;">重要度: <strong>${validationResult.重要度 || validationResult.severity || '高'}</strong></div>
      </div>
    ` : '<div style="color: var(--text-muted); font-size: 11px;">問題は検出されていません</div>';

    // 入力漏れ項目
    const missingList = container.querySelector("#missing-items");
    missingList.innerHTML = missingItems.length > 0 ? missingItems.map(m => `
      <div style="padding: 4px 6px; background: rgba(250,204,21,0.1); border-left: 2px solid #facc15; border-radius: 2px; color: var(--text); font-size: 11px;">
        ${m.漏れ項目名 || m.missing_field}: <strong>${m.漏れ項目区分 || m.field_type || '必須'}</strong>
      </div>
    `).join("") : '<div style="color: var(--text-muted); font-size: 11px;">入力漏れはありません</div>';

    // チャネル間矛盾
    const conflictList = container.querySelector("#channel-conflicts");
    conflictList.innerHTML = conflicts.length > 0 ? conflicts.map(c => `
      <div style="padding: 4px 6px; background: rgba(255,152,0,0.1); border-left: 2px solid #ff9800; border-radius: 2px; color: var(--text); font-size: 11px;">
        <strong>${c.矛盾タイプ || c.conflict_type || '矛盾'}</strong>: ${c.矛盾内容 || c.conflict_detail || ''}
      </div>
    `).join("") : '<div style="color: var(--text-muted); font-size: 11px;">矛盾は検出されていません</div>';

    // 修正履歴
    const historyList = container.querySelector("#correction-history");
    historyList.innerHTML = corrections.length > 0 ? corrections.map(c => `
      <div style="padding: 6px; background: rgba(76,175,80,0.1); border-left: 2px solid #4ade80; border-radius: 2px;">
        <div style="color: var(--text); font-weight: 500; font-size: 11px;">${c.修正項目名 || c.field_name || ''}</div>
        <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">
          <span style="display: inline-block; margin-right: 8px;">修正前: <code style="background: rgba(0,0,0,0.3); padding: 1px 3px; border-radius: 2px;">${c.修正前値 || c.old_value || ''}</code></span>
          <span style="display: inline-block;">修正後: <code style="background: rgba(0,0,0,0.3); padding: 1px 3px; border-radius: 2px;">${c.修正後値 || c.new_value || ''}</code></span>
        </div>
        <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">${new Date(c.修正日時 || c.updated_at).toLocaleString('ja-JP')}</div>
      </div>
    `).join("") : '<div style="color: var(--text-muted); font-size: 11px;">修正履歴はありません</div>';

    detailPanel.style.display = "block";
    noSelection.style.display = "none";
  }

  // 3. 初期データ表示
  renderOrderList(tables[flowTableIndex]?.records || []);

  // 4. 検索ボタン
  container.querySelector("#search-button").addEventListener("click", async () => {
    const statusFilter = container.querySelector("#status-filter").value;
    let rows = tables[flowTableIndex]?.records || [];
    if (statusFilter) {
      rows = rows.filter(r => (r.現在ステータス || r.status) === statusFilter);
    }
    renderOrderList(rows);
  });

  // 5. 承認判定送信
  container.querySelector("#submit-approval").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }

    const decision = container.querySelector("#approval-decision").value;
    const priority = container.querySelector("#approval-priority").value;
    const comment = container.querySelector("#approval-comment").value;

    if (!decision) {
      alert("判定結果を選択してください");
      return;
    }

    // 承認者判定履歴を保存（テーブルインデックス 5 と仮定）
    const approvalHistoryData = {
      受注データID: selectedOrderId,
      連携承認フローID: currentFlowData?.フロー_ID || currentFlowData?.id || '',
      承認者ユーザーID: 'current-user-id',
      判定結果: decision,
      判定理由: comment,
      判定日時: new Date().toISOString()
    };

    // 連携承認フローを更新
    if (currentFlowData) {
      const updateData = {
        現在ステータス: decision === '承認' ? '承認済' : decision === '却下' ? '却下' : '条件付承認',
        承認判定: decision,
        承認コメント: comment,
        優先度: priority,
        承認日時: new Date().toISOString()
      };
      await window.aivicApi.update(flowTableIndex, currentFlowData.フロー_ID || currentFlowData.id, updateData);
    }

    alert(`判定を送信しました: ${decision}`);
    container.querySelector("#approval-decision").value = "";
    container.querySelector("#approval-comment").value = "";

    // 一覧を再読み込み
    const updatedRows = await window.aivicApi.list(flowTableIndex);
    renderOrderList(updatedRows || tables[flowTableIndex]?.records || []);
  });

  // 6. キャンセルボタン
  container.querySelector("#cancel-approval").addEventListener("click", () => {
    container.querySelector("#approval-decision").value = "";
    container.querySelector("#approval-comment").value = "";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=受注データ修正履歴, 1=受注データ検証結果, 2=信頼度スコア, 3=チャネル情報
  const modificationHistoryTableIndex = 0;
  const validationResultTableIndex = 1;
  const trustScoreTableIndex = 2;

  // 初期データ（サンプル）
  const sampleOrderData = {
    orderId: 'ORD-20250523-001',
    customerName: '株式会社ABC',
    channel: 'Web注文',
    modifier: '田中太郎',
    modificationDatetime: '2025-05-23 14:32:15',
    trustScore: 72,
    validationResult: '警告: 入力漏れ検出'
  };

  const sampleDiffs = [
    {
      itemName: '受注金額',
      beforeValue: '¥98,000',
      afterValue: '¥100,000'
    },
    {
      itemName: '配送先住所',
      beforeValue: '東京都渋谷区',
      afterValue: '東京都渋谷区道玄坂1-2-3'
    }
  ];

  // 初期表示
  function initializeDisplay() {
    container.querySelector('[data-testid="order-id-display"]').textContent = sampleOrderData.orderId;
    container.querySelector('[data-testid="customer-name-display"]').textContent = sampleOrderData.customerName;
    container.querySelector('[data-testid="channel-display"]').textContent = sampleOrderData.channel;
    container.querySelector('[data-testid="modifier-display"]').textContent = sampleOrderData.modifier;
    container.querySelector('[data-testid="modification-datetime-display"]').textContent = sampleOrderData.modificationDatetime;
    container.querySelector('[data-testid="trust-score-display"]').textContent = sampleOrderData.trustScore;
    container.querySelector('[data-testid="validation-result-display"]').textContent = '⚠ ' + sampleOrderData.validationResult;

    renderDiffItems();
  }

  // 差分アイテムの描画
  function renderDiffItems() {
    const diffContainer = container.querySelector('#diff-container');
    diffContainer.innerHTML = sampleDiffs.map(diff => `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 12px; background: rgba(0,0,0,0.2); border-radius: 3px;">
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">修正項目: ${diff.itemName}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">修正前</div>
          <div style="font-size: 13px; color: #ff6b6b; font-family: monospace; font-weight: 600;">${diff.beforeValue}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;"></div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">修正後</div>
          <div style="font-size: 13px; color: #51cf66; font-family: monospace; font-weight: 600;">${diff.afterValue}</div>
        </div>
      </div>
    `).join('');
  }

  // 信頼度スコア変更の即座反映
  const trustScoreChangeInput = container.querySelector('[data-testid="trust-score-change"]');
  const trustScorePreview = container.querySelector('[data-testid="trust-score-preview"]');

  trustScoreChangeInput.addEventListener('input', () => {
    const change = parseInt(trustScoreChangeInput.value) || 0;
    const newScore = Math.max(0, Math.min(100, sampleOrderData.trustScore + change));
    trustScorePreview.textContent = newScore;
  });

  // 保存ボタン
  const saveButton = container.querySelector('[data-testid="save-button"]');
  saveButton.addEventListener('click', async () => {
    const reason = container.querySelector('[data-testid="correction-reason-select"]').value;
    const scoreChange = parseInt(container.querySelector('[data-testid="trust-score-change"]').value) || 0;
    const notes = container.querySelector('[data-testid="correction-notes"]').value;

    if (!reason) {
      alert('修正理由を選択してください');
      return;
    }

    if (!notes.trim()) {
      alert('修正備考を入力してください');
      return;
    }

    // 修正履歴データの構築
    const correctionHistoryData = {
      orderId: sampleOrderData.orderId,
      correctionReason: reason,
      correctionNotes: notes,
      trustScoreChange: scoreChange,
      newTrustScore: Math.max(0, Math.min(100, sampleOrderData.trustScore + scoreChange)),
      modificationDatetime: new Date().toISOString(),
      modifier: sampleOrderData.modifier,
      diffs: sampleDiffs
    };

    // API保存
    const saved = await window.aivicApi.save(modificationHistoryTableIndex, correctionHistoryData);

    if (saved) {
      alert('修正履歴を保存しました');
      // フォームをリセット
      container.querySelector('[data-testid="correction-reason-select"]').value = '';
      container.querySelector('[data-testid="trust-score-change"]').value = '0';
      container.querySelector('[data-testid="correction-notes"]').value = '';
      trustScorePreview.textContent = sampleOrderData.trustScore;
    }
  });

  // キャンセルボタン
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');
  cancelButton.addEventListener('click', () => {
    if (confirm('修正内容を破棄してもよろしいですか？')) {
      container.querySelector('[data-testid="correction-reason-select"]').value = '';
      container.querySelector('[data-testid="trust-score-change"]').value = '0';
      container.querySelector('[data-testid="correction-notes"]').value = '';
      trustScorePreview.textContent = sampleOrderData.trustScore;
      // 前画面に戻る
      window.showScreen('scr-1781413282852');
    }
  });

  // 初期化実行
  initializeDisplay();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（受注データ検証結果テーブルを想定）
  const tableIndex = 0;

  // DOM 要素の取得
  const tbody = container.querySelector("#order-tbody");
  const recordCount = container.querySelector("#record-count");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExportCsv = container.querySelector("#btn-export-csv");
  const btnDashboard = container.querySelector("#btn-dashboard");

  const filterOrderId = container.querySelector("#filter-order-id");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const filterDateTo = container.querySelector("#filter-date-to");
  const filterStatus = container.querySelector("#filter-status");
  const filterChannel = container.querySelector("#filter-channel");
  const filterScoreMin = container.querySelector("#filter-score-min");
  const filterScoreMax = container.querySelector("#filter-score-max");

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => {
      const statusColor = row.検証ステータス === "合格" ? "#4ade80" 
                        : row.検証ステータス === "不合格" ? "#ef4444"
                        : row.検証ステータス === "警告" ? "#f59e0b"
                        : "#6b7280";

      const scoreColor = (row.総合スコア || 0) >= 80 ? "#4ade80"
                       : (row.総合スコア || 0) >= 60 ? "#f59e0b"
                       : "#ef4444";

      return `
        <tr data-id="${row.id || row.検証結果ID}" style="border-bottom: 1px solid var(--border); background: var(--bg-main);">
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text); font-family: monospace;">${row.受注データID || row.id || "-"}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "-"}</td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text);">${row.チャネル名 || "-"}</td>
          <td style="padding: 10px 12px; font-size: 13px;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-weight: 500; font-size: 12px;">
              ${row.検証ステータス || "-"}
            </span>
          </td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text); text-align: center;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${scoreColor}20; color: ${scoreColor}; font-weight: 600;">
              ${row.総合スコア || row.信頼度スコア || 0}
            </span>
          </td>
          <td style="padding: 10px 12px; font-size: 13px; color: var(--text); max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${row.エラーメッセージ || row.検証結果 || ""}">
            ${row.エラーメッセージ ? row.エラーメッセージ.substring(0, 30) + "..." : row.検証結果 || "-"}
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.id || row.検証結果ID}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
    recordCount.textContent = `件数: ${rows.length}`;
  }

  // 2. 初期データ描画
  renderRows(tables[tableIndex]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  btnSearch.addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(tableIndex) || tables[tableIndex]?.records || [];

    const filtered = allRows.filter(row => {
      const orderId = (row.受注データID || row.id || "").toString().toLowerCase();
      const keyword = filterOrderId.value.toLowerCase();
      if (keyword && !orderId.includes(keyword)) return false;

      const dateFrom = filterDateFrom.value ? new Date(filterDateFrom.value) : null;
      const dateTo = filterDateTo.value ? new Date(filterDateTo.value) : null;
      const rowDate = row.検証実行日時 ? new Date(row.検証実行日時) : null;
      if (dateFrom && rowDate && rowDate < dateFrom) return false;
      if (dateTo && rowDate && rowDate > new Date(dateTo.getTime() + 86400000)) return false;

      const status = filterStatus.value;
      if (status && row.検証ステータス !== status) return false;

      const channel = filterChannel.value;
      if (channel && row.チャネル名 !== channel) return false;

      const scoreMin = filterScoreMin.value ? parseInt(filterScoreMin.value) : 0;
      const scoreMax = filterScoreMax.value ? parseInt(filterScoreMax.value) : 100;
      const score = row.総合スコア || row.信頼度スコア || 0;
      if (score < scoreMin || score > scoreMax) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  btnReset.addEventListener("click", () => {
    filterOrderId.value = "";
    filterDateFrom.value = "";
    filterDateTo.value = "";
    filterStatus.value = "";
    filterChannel.value = "";
    filterScoreMin.value = "";
    filterScoreMax.value = "";
    renderRows(tables[tableIndex]?.records || []);
  });

  // 5. CSVエクスポート
  btnExportCsv.addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(tableIndex) || tables[tableIndex]?.records || [];
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "受注日時", "チャネル", "検証ステータス", "信頼度スコア", "エラーメッセージ", "重要度"];
    const rows = allRows.map(row => [
      row.受注データID || row.id || "",
      row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "",
      row.チャネル名 || "",
      row.検証ステータス || "",
      row.総合スコア || row.信頼度スコア || "",
      row.エラーメッセージ || "",
      row.重要度 || ""
    ]);

    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `order_status_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 6. ダッシュボードボタン
  btnDashboard.addEventListener("click", () => {
    window.showScreen("scr-1781413262699");
  });

  // 7. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      // 詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852", { recordId });
    }
  });
}

function(container, apiUrl, tables) {
