      const severityColor = r.重要度 === '致命的' ? '#ff6b6b' : r.重要度 === '高' ? '#ff9500' : r.重要度 === '中' ? '#fbbf24' : '#9fb0d1';
      return `<tr data-id="${r.検証結果ID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;">
