      tbody.innerHTML = '<tr style="text-align: center; color: var(--text-muted); padding: 2rem;"><td colspan="9">修正対象がありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const priorityColor = r.優先度レベル === 1 ? '#ff6b6b' : r.優先度レベル === 2 ? '#ff9500' : r.優先度レベル === 3 ? '#fbbf24' : '#9fb0d1';
