        <td style="padding: 0.5rem; text-align: center;"><span style="background: ${priorityColor}20; color: ${priorityColor}; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-weight: 600; font-size: 0.75rem;">P${r.優先度レベル || '-'}</span></td>
