        </td>
      </tr>`;
    }).join("");
  }

  function updateKPIs(rows) {
    const total = rows.length;
    const passed = rows.filter(r => r.検証ステータス === '合格').length;
    const pending = rows.filter(r => r.対応状況 === '未対応').length;
    const avgConfidence = rows.length > 0 ? Math.round(rows.reduce((sum, r) => sum + (r.信頼度スコア || 0), 0) / rows.length) : 0;

    container.querySelector("[data-testid='kpi-total-validations']").textContent = total;
    container.querySelector("[data-testid='kpi-pass-rate']").textContent = total > 0 ? Math.round((passed / total) * 100) + '%' : '0%';
    container.querySelector("[data-testid='kpi-pending-errors']").textContent = pending;
    container.querySelector("[data-testid='kpi-avg-confidence']").textContent = avgConfidence;
  }

  // ============ 2. 初期データ読み込み ============
  async function loadValidationData() {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      renderValidationRows(rows);
      updateKPIs(rows);
