    const filtered = rows.filter(r => {
      if (statusFilter && r.検証ステータス !== statusFilter) return false;
      if (channelFilter && r.チャネル !== channelFilter) return false;
      if (severityFilter && r.重要度 !== severityFilter) return false;
      if (responseFilter && r.対応状況 !== responseFilter) return false;
      return true;
    });

    renderValidationRows(filtered);
    updateKPIs(filtered);
  });

  // ============ 4. CSV出力ボタン ============
  container.querySelector("[data-testid='export-button']").addEventListener("click", async () => {
