      else if (scoreValue < 75) scoreColor = "#ffc107"; // 中

      return `
        <tr data-id="${score.信頼度スコアID}" class="score-row" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 8px; color: var(--text);">${score.受注データID || "-"}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="font-weight: 600; color: ${scoreColor};">${scoreValue}</span>
          </td>
          <td style="padding: 8px; text-align: center;">
            ${warningFlag ? `<span style="display: inline-block; padding: 2px 6px; background: rgba(255,82,82,0.2); color: #ff5252; border-radius: 2px; font-size: 10px; font-weight: 600;">${warningLevel}</span>` : `<span style="color: var(--text-muted);">-</span>`}
          </td>
          <td style="padding: 8px; text-align: center;">
            ${correctionFlag ? `<span style="display: inline-block; padding: 2px 6px; background: rgba(255,193,7,0.2); color: #ffc107; border-radius: 2px; font-size: 10px; font-weight: 600;">要修正</span>` : `<span style="color: var(--text-muted);">-</span>`}
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    container.querySelectorAll(".score-row").forEach(row => {
      row.addEventListener("click", () => {
        const scoreId = row.dataset.id;
        selectScore(scoreId);
      });
    });
  }

  // ============ 2. 初期データ読み込み ============
  async function loadInitialData() {
    const scores = await window.aivicApi.list(SCORE_TABLE_IDX);
    if (scores) {
      allScores = scores;
      renderScoreList(allScores);
    }
  }

  // ============ 3. スコア選択 ============
  async function selectScore(scoreId) {
    selectedScoreId = scoreId;
    const score = allScores.find(s => s.信頼度スコアID === scoreId);
    if (!score) return;

    // OCR読み込み結果を取得
    const ocrResults = await window.aivicApi.list(OCR_TABLE_IDX);
    const ocrResult = ocrResults?.find(o => o.受注データID === score.受注データID);

    // 詳細パネルを表示
    emptyState.style.display = "none";
    detailPanel.style.display = "block";

    // ヘッダー更新
    detailHeader.innerHTML = `<span style="color: var(--text);">受注ID: ${score.受注データID || "-"}</span>`;

    // OCR読み込み結果セクション
    container.querySelector("#detail-doc-type").textContent = ocrResult?.source_document_type || "-";
    container.querySelector("#detail-ocr-engine").textContent = ocrResult?.ocr_engine_version || "-";
    container.querySelector("#detail-raw-text").textContent = ocrResult?.raw_ocr_text || "-";

    // 信頼度スコアセクション
    const totalScore = score.総合スコア || 0;
    container.querySelector("#detail-total-score").textContent = totalScore;
    container.querySelector("#detail-score-gauge").querySelector("div").style.width = totalScore + "%";
    container.querySelector("#detail-warning-level").textContent = score.警告レベル || "-";
    container.querySelector("#detail-completeness").textContent = (score.完全性スコア || 0) + "%";
    container.querySelector("#detail-accuracy").textContent = (score.正確性スコア || 0) + "%";
    container.querySelector("#detail-consistency").textContent = (score.一貫性スコア || 0) + "%";
    container.querySelector("#detail-score-date").textContent = score.スコア計算日時 ? new Date(score.スコア計算日時).toLocaleString("ja-JP") : "-";

    // 修正前後比較（修正履歴から取得）
    const correctionHistory = await window.aivicApi.list(CORRECTION_HISTORY_IDX);
    const lastCorrection = correctionHistory?.find(c => c.受注データID === score.受注データID);
    container.querySelector("#detail-before-value").textContent = lastCorrection?.修正前値 || "-";
    container.querySelector("#detail-after-value").textContent = lastCorrection?.修正後値 || "-";

    // 修正フォーム初期化
    container.querySelector("#input-correction-field").value = lastCorrection?.修正項目名 || "-";
    container.querySelector("#input-correction-value").value = "";
    container.querySelector("#select-correction-reason").value = "";
    container.querySelector("#textarea-correction-comment").value = "";
  }

  // ============ 4. 検索ボタン ============
  btnSearch.addEventListener("click", () => {
    const orderId = inputOrderId.value.trim();
    const scoreRange = selectScoreRange.value;
    const prioritySort = selectPrioritySort.value;

    let filtered = [...allScores];

    // 受注ID検索
    if (orderId) {
      filtered = filtered.filter(s => (s.受注データID || "").includes(orderId));
    }

    // 信頼度範囲フィルタ
    if (scoreRange) {
      const [min, max] = scoreRange.split("-").map(Number);
      filtered = filtered.filter(s => {
        const score = s.総合スコア || 0;
        return score >= min && score <= max;
      });
    }

    // 優先度ソート
    if (prioritySort === "score-asc") {
      filtered.sort((a, b) => (a.総合スコア || 0) - (b.総合スコア || 0));
    } else if (prioritySort === "score-desc") {
      filtered.sort((a, b) => (b.総合スコア || 0) - (a.総合スコア || 0));
    } else if (prioritySort === "priority-asc") {
      filtered.sort((a, b) => {
        const priorityA = a.警告フラグ ? 1 : 0;
        const priorityB = b.警告フラグ ? 1 : 0;
        return priorityB - priorityA;
      });
    }

    renderScoreList(filtered);
  });

  // ============ 5. 修正保存ボタン ============
  btnSaveCorrection.addEventListener("click", async () => {
    if (!selectedScoreId) {
      alert("受注を選択してください");
      return;
    }

    const score = allScores.find(s => s.信頼度スコアID === selectedScoreId);
    if (!score) return;

    const correctionValue = container.querySelector("#input-correction-value").value.trim();
    const correctionReason = container.querySelector("#select-correction-reason").value;
    const correctionComment = container.querySelector("#textarea-correction-comment").value.trim();

    if (!correctionValue || !correctionReason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    // 修正履歴を保存
    const correctionRecord = {
      受注データID: score.受注データID,
      修正項目名: container.querySelector("#input-correction-field").value,
      修正前値: container.querySelector("#detail-before-value").textContent,
      修正後値: correctionValue,
      修正理由: correctionReason,
      修正備考: correctionComment,
      修正ユーザーID: "current-user-id", // 実装時は認証情報から取得
      修正日時: new Date().toISOString(),
      検証結果ID: selectedScoreId
    };

    const saved = await window.aivicApi.save(CORRECTION_HISTORY_IDX, correctionRecord);
    if (saved) {
      alert("修正を保存しました");
      // 修正後、スコアを再計算（実装時は API 呼び出し）
      loadInitialData();
      selectScore(selectedScoreId);
    }
  });

  // ============ 6. キャンセルボタン ============
  btnCancelCorrection.addEventListener("click", () => {
    container.querySelector("#input-correction-value").value = "";
    container.querySelector("#select-correction-reason").value = "";
    container.querySelector("#textarea-correction-comment").value = "";
  });

  // ============ 7. 初期化 ============
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定（受注データ検証結果テーブル）
  const validationResultsIndex = tables.findIndex(t => t.tableName === "受注データ検証結果") || 0;
  const trustScoreIndex = tables.findIndex(t => t.tableName === "信頼度スコア") || 1;
  const duplicateIndex = tables.findIndex(t => t.tableName === "重複受注検出結果") || 2;
  const channelConflictIndex = tables.findIndex(t => t.tableName === "チャネル間矛盾検出結果") || 3;
  const missingInputIndex = tables.findIndex(t => t.tableName === "入力漏れ検出結果") || 4;

  // 状態管理
  let allOrders = [];
  let filteredOrders = [];
  let selectedOrderIds = new Set();
  let isProcessing = false;

  // ===== 1. 受注一覧の再描画関数 =====
  function renderOrderList(orders) {
    const tbody = container.querySelector("#order-tbody");
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">検証対象受注がありません</td></tr>';
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.id);
      const scoreColor = order.totalScore >= 80 ? '#4caf50' : order.totalScore >= 60 ? '#ffa500' : '#ff6a00';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);" data-id="${order.id}">
          <td style="padding: 8px; text-align: center;">
            <input type="checkbox" class="order-checkbox" data-id="${order.id}" ${isSelected ? 'checked' : ''} style="accent-color: var(--primary);" />
          </td>
          <td style="padding: 8px; color: var(--text);">${order.orderId || order.id.substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text);">${order.channel || 'WEB'}</td>
          <td style="padding: 8px; color: var(--text);">${order.customerName || '—'}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(order.amount || 0).toLocaleString()}</td>
          <td style="padding: 8px; color: ${scoreColor}; font-weight: 600;">${order.totalScore || 0}</td>
          <td style="padding: 8px; color: var(--text);">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${
              order.validationStatus === '合格' ? 'rgba(76,175,80,0.2); color: #4caf50;' :
              order.validationStatus === '不合格' ? 'rgba(255,106,0,0.2); color: #ff6a00;' :
              order.validationStatus === '警告' ? 'rgba(255,165,0,0.2); color: #ffa500;' :
              'rgba(200,200,200,0.2); color: var(--text-muted);'
            }">
              ${order.validationStatus || '保留'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${order.id}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    // チェックボックスイベント
    container.querySelectorAll(".order-checkbox").forEach(cb => {
      cb.addEventListener("change", e => {
        const orderId = e.target.dataset.id;
        if (e.target.checked) {
          selectedOrderIds.add(orderId);
        } else {
          selectedOrderIds.delete(orderId);
        }
        updateSelectAllCheckbox();
      });
    });

    // 詳細ボタン
    container.querySelectorAll(".detail-btn").forEach(btn => {
      btn.addEventListener("click", e => {
        const orderId = e.target.dataset.id;
        window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
      });
    });
  }

  // ===== 2. 全選択チェックボックス =====
  function updateSelectAllCheckbox() {
    const selectAll = container.querySelector("#select-all");
    const checkboxes = container.querySelectorAll(".order-checkbox");
    selectAll.checked = checkboxes.length > 0 && Array.from(checkboxes).every(cb => cb.checked);
  }

  container.querySelector("#select-all").addEventListener("change", e => {
    const isChecked = e.target.checked;
    container.querySelectorAll(".order-checkbox").forEach(cb => {
      cb.checked = isChecked;
      const orderId = cb.dataset.id;
      if (isChecked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }
    });
  });

  // ===== 3. フィルタ適用 =====
  container.querySelector("#btn-filter-apply").addEventListener("click", async () => {
    const orderId = container.querySelector("#filter-order-id").value.trim();
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    filteredOrders = allOrders.filter(order => {
      if (orderId && !order.id.includes(orderId) && !(order.orderId || "").includes(orderId)) return false;
      if (channel && order.channel !== channel) return false;
      if (status && order.validationStatus !== status) return false;
      return true;
    });

    selectedOrderIds.clear();
    renderOrderList(filteredOrders);
  });

  // ===== 4. フィルタリセット =====
  container.querySelector("#btn-filter-reset").addEventListener("click", () => {
    container.querySelector("#filter-order-id").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-status").value = "";
    filteredOrders = [...allOrders];
    selectedOrderIds.clear();
    renderOrderList(filteredOrders);
  });

  // ===== 5. 一括再検証実行 =====
  container.querySelector("#btn-execute-batch").addEventListener("click", async () => {
    if (isProcessing) return;

    const selectedRules = {
      duplicate: container.querySelector("#rule-duplicate").checked,
      channelConflict: container.querySelector("#rule-channel-conflict").checked,
      missingInput: container.querySelector("#rule-missing-input").checked,
      ocrVerify: container.querySelector("#rule-ocr-verify").checked
    };

    if (!Object.values(selectedRules).some(v => v)) {
      alert("検証ルールを1つ以上選択してください");
      return;
    }

    const ordersToProcess = filteredOrders.length > 0 ? filteredOrders : allOrders;
    if (ordersToProcess.length === 0) {
      alert("検証対象受注がありません");
      return;
    }

    await executeValidation(ordersToProcess, selectedRules);
  });

  // ===== 6. 選択行のみ実行 =====
  container.querySelector("#btn-execute-selected").addEventListener("click", async () => {
    if (isProcessing) return;

    if (selectedOrderIds.size === 0) {
      alert("検証対象受注を選択してください");
      return;
    }

    const selectedRules = {
      duplicate: container.querySelector("#rule-duplicate").checked,
      channelConflict: container.querySelector("#rule-channel-conflict").checked,
      missingInput: container.querySelector("#rule-missing-input").checked,
      ocrVerify: container.querySelector("#rule-ocr-verify").checked
    };

    if (!Object.values(selectedRules).some(v => v)) {
      alert("検証ルールを1つ以上選択してください");
      return;
    }

    const ordersToProcess = allOrders.filter(o => selectedOrderIds.has(o.id));
    await executeValidation(ordersToProcess, selectedRules);
  });

  // ===== 7. 検証実行メイン処理 =====
  async function executeValidation(orders, rules) {
    isProcessing = true;
    const progressPanel = container.querySelector("#progress-panel");
    const resultPanel = container.querySelector("#result-panel");
    resultPanel.style.display = "none";
    progressPanel.style.display = "block";

    const total = orders.length;
    let processed = 0;
    let improved = 0;
    let warnings = 0;
    let errors = 0;

    for (const order of orders) {
      try {
        // 各ルールを実行
        if (rules.duplicate) {
          // 重複検出ロジック（シミュレーション）
          const hasDuplicate = Math.random() > 0.7;
          if (hasDuplicate) warnings++;
        }

        if (rules.channelConflict) {
          // チャネル間矛盾検出（シミュレーション）
          const hasConflict = Math.random() > 0.8;
          if (hasConflict) warnings++;
        }

        if (rules.missingInput) {
          // 入力漏れ検出（シミュレーション）
          const hasMissing = Math.random() > 0.75;
          if (hasMissing) warnings++;
        }

        if (rules.ocrVerify) {
          // OCR確認（シミュレーション）
          const ocrError = Math.random() > 0.85;
          if (ocrError) errors++;
        }

        // スコア算出（シミュレーション）
        const oldScore = order.totalScore || 70;
        const newScore = Math.min(100, oldScore + Math.floor(Math.random() * 15));
        if (newScore > oldScore) improved++;

        // 検証結果を保存（API呼び出し）
        await window.aivicApi.save(validationResultsIndex, {
          orderId: order.id,
          validationStatus: newScore >= 80 ? "合格" : newScore >= 60 ? "警告" : "不合格",
          totalScore: newScore,
          executedRules: Object.keys(rules).filter(k => rules[k]).join(","),
          executedAt: new Date().toISOString()
        });

        processed++;
        container.querySelector("#progress-count").textContent = processed;
        container.querySelector("#progress-total").textContent = total;
        container.querySelector("#progress-bar").style.width = (processed / total * 100) + "%";

      } catch (err) {
        console.error("検証エラー:", err);
        errors++;
      }
    }

    // 処理完了
    isProcessing = false;
    progressPanel.style.display = "none";
    resultPanel.style.display = "block";

    container.querySelector("#result-processed").textContent = processed;
    container.querySelector("#result-improved").textContent = improved;
    container.querySelector("#result-warnings").textContent = warnings;
    container.querySelector("#result-errors").textContent = errors;

    // 一覧を再読み込み
    await loadOrderList();
  }

  // ===== 8. 結果詳細表示 =====
  container.querySelector("#btn-view-results").addEventListener("click", () => {
    window.showScreen("scr-1781413382983"); // 受注データ検証結果レポート画面
  });

  // ===== 9. 初期データ読み込み =====
  async function loadOrderList() {
    try {
      const validationResults = await window.aivicApi.list(validationResultsIndex);
      const trustScores = await window.aivicApi.list(trustScoreIndex);

      // 検証結果とスコアをマージ
      allOrders = (validationResults || []).map(vr => {
        const score = (trustScores || []).find(ts => ts.orderId === vr.orderId);
        return {
          id: vr.id || vr.orderId,
          orderId: vr.orderId || vr.id.substring(0, 8),
          channel: vr.channel || "WEB",
          customerName: vr.customerName || "—",
          amount: vr.amount || 0,
          totalScore: score?.totalScore || vr.totalScore || 70,
          validationStatus: vr.validationStatus || "保留"
        };
      });

      filteredOrders = [...allOrders];
      renderOrderList(filteredOrders);
    } catch (err) {
      console.error("データ読み込みエラー:", err);
      allOrders = [];
      filteredOrders = [];
      renderOrderList([]);
    }
  }

  // 初期化
  loadOrderList();
}
